WITH piligrim_dest_list AS ( SELECT DISTINCT dest_id FROM ( /* Old List (107 Cities) */ -- VALUES -- (70346),(808),(83409),(216354),(1585),(217362),(975),(759),(216346),(65815), -- (247),(307614),(289873),(76480),(204358),(298723),(82558),(75103),(517), -- (265316),(231),(1529),(879),(217335),(1242),(71642),(93968),(74124),(142), -- (636),(1136),(520),(669),(1061),(77167),(275),(69526),(802),(196),(1528), -- (77530),(200347),(305974),(68747),(735),(84848),(197504),(216551),(68705), -- (1343),(80438),(427),(77687),(73533),(196096),(202212),(711),(78796),(489), -- (747),(93580),(466),(77705),(68871),(1148),(1459),(361),(471),(70983), -- (81826),(501),(987),(93189),(76187),(196752),(84832),(74690),(1219), -- (94515),(1007),(65805),(496),(194482),(94509),(198868),(842),(69475), -- (74130),(215191),(84310),(1496),(403),(1141),(189),(133),(177),(1351), -- (70628),(74708),(66007),(198750),(663),(94877),(71756),(1128),(293),(534), -- (77093),(154),(1001),(70030),(576),(70429),(217),(960),(196420),(134), -- (205655),(94782),(300439) /* New List (120 Cities) */ VALUES (70346),(808),(83409),(216354),(1585),(217362),(975),(759),(216346),(65815),(247), (307614),(289873),(76480),(204358),(298723),(82558),(75103),(517),(265316),(231), (1529),(879),(217335),(1242),(71642),(93968),(74124),(142),(636),(1136),(520),(669), (1061),(77167),(275),(69526),(802),(196),(1528),(77530),(200347),(305974),(68747), (735),(84848),(197504),(216551),(68705),(1343),(80438),(427),(77687),(73533),(196096), (202212),(711),(78796),(489),(747),(93580),(466),(77705),(68871),(1148),(1459),(361), (471),(70983),(81826),(501),(987),(93189),(76187),(196752),(84832),(74690),(1219), (94515),(1007),(65805),(496),(194482),(94509),(198868),(842),(69475),(74130),(215191), (84310),(1496),(403),(1141),(189),(133),(177),(1351),(70628),(74708),(66007),(198750), (663),(94877),(71756),(1128),(293),(534),(77093),(154),(1001),(70030),(576),(70429), (217),(960),(196420),(94782),(300439) ) AS x(dest_id) ), ui AS ( SELECT event_value, mri_session_id, mri_client_id FROM user_interaction.ui_ux_events WHERE __time >= TIMESTAMP '2026-01-01 00:00:00' AND __time < TIMESTAMP '2026-02-01 00:00:00' AND event_name = 'Tuple clicked' AND event_value IN ('RTR available', 'RTR not available') AND event_src = 'Android' AND header_country = 'IND' ), co AS ( SELECT bt.rb_user_id, bt.source_location_id AS base_src_id, bt.destination_location_id AS base_dest_id, bt.tin, bt.time_of_event AS txted_date, bt.mri_session_id, bt.mri_client_id, CASE WHEN pdl.dest_id IS NOT NULL THEN 'Pilgrim' ELSE 'non-Pilgrim' END AS Pilgrim FROM transaction.bus_ticket_events bt LEFT JOIN piligrim_dest_list pdl ON bt.destination_location_id = pdl.dest_id WHERE bt.time_of_event >= TIMESTAMP '2026-01-01 00:00:00' AND bt.time_of_event < TIMESTAMP '2026-02-01 00:00:00' AND bt.sales_channel IN ('RB:MOBILEWEB#droidapp', 'DROIDAPP') AND bt.country_code = 'IND' AND bt.event_class = 2 AND bt.event_type = 101 AND bt.tin IS NOT NULL AND bt.rb_user_id > 0 AND bt.business_unit = 'REDBUS_IN' ), -- OPTIMIZED: Pre-filter search details to only users who actually booked in Nov filtered_searches AS ( SELECT s.rb_user_id, s.src_id, s.dest_id, s.__time as searchdate FROM user_interaction.search_details s WHERE s.__time >= TIMESTAMP '2026-01-01 00:00:00' AND s.__time < TIMESTAMP '2026-02-16 00:00:00' -- Extra 15 days AND s.os = 'Android' AND s.country = 'IND' AND s.rb_user_id IN (SELECT DISTINCT rb_user_id FROM co) -- Crucial for pruning ), all_post_search AS ( SELECT b.rb_user_id, b.base_src_id, b.base_dest_id, b.txted_date, s.searchdate, s.src_id, s.dest_id FROM co b INNER JOIN filtered_searches s ON s.rb_user_id = b.rb_user_id WHERE s.src_id = b.base_dest_id AND s.dest_id = b.base_src_id AND s.searchdate > b.txted_date AND s.searchdate < date_add('day', 15, b.txted_date) ), -- Pre-filter return tickets to only relevant users return_tickets AS ( SELECT r.rb_user_id, r.source_location_id, r.destination_location_id, MIN(r.time_of_event) as first_ret_date FROM transaction.bus_ticket_events r WHERE r.time_of_event >= TIMESTAMP '2026-01-01 00:00:00' AND r.time_of_event < TIMESTAMP '2026-02-16 00:00:00' AND r.rb_user_id IN (SELECT DISTINCT rb_user_id FROM all_post_search) AND r.sales_channel IN ('RB:MOBILEWEB#droidapp', 'DROIDAPP') AND r.event_class = 2 AND r.event_type = 101 GROUP BY 1, 2, 3 ) SELECT co.Pilgrim, COALESCE(ui.event_value, 'Unknown') AS rtr_type, -- 'Overall' AS rtr_type, COUNT(DISTINCT co.rb_user_id) AS "Txted Users", COUNT(DISTINCT aps.rb_user_id) AS "Searched for return", COUNT(DISTINCT rt.rb_user_id) AS "Txted for Return" FROM co LEFT JOIN ui ON ui.mri_session_id = co.mri_session_id AND ui.mri_client_id = co.mri_client_id LEFT JOIN all_post_search aps ON aps.rb_user_id = co.rb_user_id AND aps.src_id = co.base_dest_id AND aps.dest_id = co.base_src_id LEFT JOIN return_tickets rt ON rt.rb_user_id = aps.rb_user_id AND rt.source_location_id = aps.src_id AND rt.destination_location_id = aps.dest_id AND rt.first_ret_date > aps.searchdate -- logic check GROUP BY 1, 2 ORDER BY 1, 2;
